private List<Envelope> queueCommand(String connectionId, QueueCommand command) {
    try {
        FollowUpQueue queue = switch (command.getOperationCase()) {
            case REORDER -> prompts.store().reorderQueue(command.getSessionId(),
                    command.getReorder().getItemIdsList(), command.getExpectedQueueRevision());
            case PROMOTE -> prompts.store().promote(command.getSessionId(),
                    command.getPromote().getItemId(), command.getExpectedQueueRevision());
            case REMOVE -> prompts.store().remove(command.getSessionId(),
                    command.getRemove().getItemId(), command.getRemove().getRequestingClientId(),
                    command.getExpectedQueueRevision()).queue();
            case RESUME -> prompts.resumeQueue(command.getSessionId(), command.getExpectedQueueRevision());
            case OPERATION_NOT_SET -> throw new IllegalArgumentException("queue operation is missing");
        };
        return List.of(stateAck(connectionId, command.getCommandId(), command.getSessionId(), queue.revision()));
    } catch (IllegalArgumentException exception) {
        return List.of(error(connectionId, "protocol.invalid_message", "invalid_queue_command"));
    } catch (JiException exception) {
        return List.of(error(connectionId, exception));
    }
}

private List<Envelope> composerCommand(String connectionId, ComposerConfigCommand command) {
    try {
        HostStorePersistence.ComposerConfig config = prompts.store().updateComposerConfig(
                command.getSessionId(), command.getExpectedConfigRevision(), command.getProfileId(),
                command.getModelId(), command.getReasoning(), command.getPermissionMode());
        return List.of(stateAck(
                connectionId, command.getCommandId(), command.getSessionId(), config.revision()));
    } catch (IllegalArgumentException exception) {
        return List.of(error(connectionId, "protocol.invalid_message", "invalid_composer_command"));
    } catch (JiException exception) {
        return List.of(error(connectionId, exception));
    }
}

private Envelope stateAck(
        String connectionId, String commandId, String sessionId, long revision) {
    HostStore.Snapshot snapshot = prompts.store().snapshot(sessionId);
    return envelope(connectionId).setHostStateAck(HostStateAck.newBuilder()
            .setCommandId(commandId)
            .setSessionId(sessionId)
            .setRevision(revision)
            .setEventSeq(snapshot.baseEventSeq())
            .setPayload(ByteString.copyFrom(snapshot.payload()))).build();
}

